import { Readable } from "node:stream";

export interface ByteRange {
  start: number;
  endExclusive: number;
}

export interface SegmentMeta {
  key: string;
  sizeBytes: number;
  contentType: string;
}

export interface SegmentStore {
  stat(key: string): Promise<SegmentMeta | null>;
  open(key: string, range?: ByteRange): Promise<Readable>;
}

export class InMemorySegmentStore implements SegmentStore {
  private readonly blobs = new Map<string, { data: Buffer; contentType: string }>();

  put(key: string, data: Buffer, contentType: string): void {
    this.blobs.set(key, { data, contentType });
  }

  async stat(key: string): Promise<SegmentMeta | null> {
    const blob = this.blobs.get(key);
    if (!blob) return null;
    return { key, sizeBytes: blob.data.length, contentType: blob.contentType };
  }

  async open(key: string, range?: ByteRange): Promise<Readable> {
    const blob = this.blobs.get(key);
    if (!blob) throw new Error(`segment not found: ${key}`);
    const slice = range ? blob.data.subarray(range.start, range.endExclusive) : blob.data;
    return Readable.from([slice]);
  }
}

import { createReadStream } from "node:fs";
import { stat as fsStat } from "node:fs/promises";
import path from "node:path";
import { Readable } from "node:stream";
import { ByteRange, SegmentMeta, SegmentStore } from "./segmentStore";

const CONTENT_TYPES: Record<string, string> = {
  ".ts": "video/mp2t",
  ".m4s": "video/iso.segment",
  ".mp4": "video/mp4",
};

export class FileSegmentStore implements SegmentStore {
  constructor(private readonly root: string) {}

  private resolve(key: string): string {
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) {
      throw new Error(`invalid segment key: ${key}`);
    }
    return full;
  }

  async stat(key: string): Promise<SegmentMeta | null> {
    try {
      const s = await fsStat(this.resolve(key));
      const ext = path.extname(key);
      return {
        key,
        sizeBytes: s.size,
        contentType: CONTENT_TYPES[ext] ?? "application/octet-stream",
      };
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }

  async open(key: string, range?: ByteRange): Promise<Readable> {
    const file = this.resolve(key);
    if (!range) return createReadStream(file);
    return createReadStream(file, { start: range.start, end: range.endExclusive });
  }
}

import type { IncomingMessage, ServerResponse } from "node:http";
import { pipeline } from "node:stream/promises";
import { ByteRange, SegmentStore } from "./segmentStore";

export function parseRange(header: string | undefined, size: number): ByteRange | null | "invalid" {
  if (!header) return null;
  const m = /^bytes=(\d*)-(\d*)$/.exec(header.trim());
  if (!m || (m[1] === "" && m[2] === "")) return "invalid";

  if (m[1] === "") {
    const suffix = Number(m[2]);
    if (suffix === 0) return "invalid";
    return { start: Math.max(0, size - suffix), endExclusive: size };
  }

  const start = Number(m[1]);
  const lastInclusive = m[2] === "" ? size - 1 : Math.min(Number(m[2]), size - 1);
  if (start >= size || start > lastInclusive) return "invalid";
  return { start, endExclusive: lastInclusive + 1 };
}

export function makeSegmentHandler(store: SegmentStore) {
  return async (req: IncomingMessage, res: ServerResponse, key: string): Promise<void> => {
    const meta = await store.stat(key);
    if (!meta) {
      res.writeHead(404).end();
      return;
    }

    const range = parseRange(req.headers.range, meta.sizeBytes);
    if (range === "invalid") {
      res.writeHead(416, { "Content-Range": `bytes */${meta.sizeBytes}` }).end();
      return;
    }

    const headers: Record<string, string | number> = {
      "Content-Type": meta.contentType,
      "Accept-Ranges": "bytes",
      "Cache-Control": "public, max-age=31536000, immutable",
    };

    if (range) {
      headers["Content-Range"] = `bytes ${range.start}-${range.endExclusive - 1}/${meta.sizeBytes}`;
      headers["Content-Length"] = range.endExclusive - range.start;
      res.writeHead(206, headers);
    } else {
      headers["Content-Length"] = meta.sizeBytes;
      res.writeHead(200, headers);
    }

    const body = await store.open(key, range ?? undefined);
    await pipeline(body, res);
  };
}
